<?php $title='Attendance'; require_once __DIR__.'/../partials/header.php'; $db=new Database(); $conn=$db->getConnection(); $employees=$conn->query("SELECT id,employee_code,name FROM employees WHERE status='active' ORDER BY name")->fetch_all(MYSQLI_ASSOC); $a=new Attendance($conn); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf($_POST['csrf_token']??null);$a->save((int)$_POST['employee_id'],$_POST['attendance_date'],$_POST['status'],$_POST['entry_time']?:null,$_POST['exit_time']?:null);redirect('attendance.php');}catch(Throwable $e){$error=$e->getMessage() ?: 'Unable to save attendance.';}} $rows=$a->recent(); ?>
<section class="panel"><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><div class="panel-head"><h2>Mark Attendance</h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>Employee</label><select class="select" name="employee_id" required><?php foreach($employees as $e):?><option value="<?=$e['id']?>"><?=e($e['employee_code'].' — '.$e['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Date</label><input class="input" type="date" name="attendance_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Status</label><select class="select" name="status"><option>present</option><option>absent</option><option>late</option><option>half_day</option><option>leave</option></select></div><div class="field"><label>Entry Time</label><input class="input" type="time" name="entry_time"></div><div class="field"><label>Exit Time</label><input class="input" type="time" name="exit_time"></div><div style="align-self:end"><button class="btn btn-primary">Save Attendance</button></div></form></section><section class="panel"><div class="panel-head"><h2>Recent Attendance</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Employee</th><th>Status</th><th>Entry</th><th>Exit</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['attendance_date'])?></td><td><?=e($r['employee_code'].' — '.$r['name'])?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e($r['entry_time'])?></td><td><?=e($r['exit_time'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php require_once __DIR__.'/../partials/footer.php'; ?>
